package ai.agrinexus.mapintel;
import android.content.Context;import org.json.*;import javax.net.ssl.HttpsURLConnection;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.security.MessageDigest;import java.util.*;import java.util.zip.GZIPInputStream;
final class Api {
 static final String ORIGIN="https://mapintel.agrinexus.ai",API="/api/EstateAtlas";String cookie="";final File cache;
 Api(Context context){cache=new File(context.getFilesDir(),"http-cache");cache.mkdirs();}
 static String readText(File file)throws IOException{return new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8);}
 static class Failure extends IOException {final int status;Failure(int status,String message){super(message);this.status=status;}}
 static String sha(byte[] b)throws Exception {StringBuilder s=new StringBuilder();for(byte n:MessageDigest.getInstance("SHA-256").digest(b))s.append(String.format(Locale.ROOT,"%02x",n&255));return s.toString();}
 static byte[] read(InputStream in,int limit)throws IOException {try(in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("Response exceeds the supported mobile size.");out.write(b,0,n);}return out.toByteArray();}}
 HttpsURLConnection open(String path)throws Exception {if(!path.startsWith(API+"/")&&!path.equals("/api/v1/users/login")&&!path.equals("/api/v1/users/logout"))throw new IOException("Untrusted API path.");URL u=new URL(ORIGIN+path);HttpsURLConnection c=(HttpsURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(120000);c.setRequestProperty("Origin",ORIGIN);c.setRequestProperty("X-Mapping-Client","1");c.setRequestProperty("Accept-Encoding","gzip");c.setRequestProperty("User-Agent","MapIntel-Android/"+BuildConfig.VERSION_NAME);if(!cookie.isEmpty())c.setRequestProperty("Cookie",cookie);return c;}
 byte[] body(HttpsURLConnection c,int limit)throws Exception {InputStream in=c.getInputStream();if("gzip".equalsIgnoreCase(c.getContentEncoding()))in=new GZIPInputStream(in);return read(in,limit);}
 void login(String username,String password,boolean remember)throws Exception {HttpsURLConnection c=open("/api/v1/users/login");try{c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");byte[] data=new JSONObject().put("login",username).put("password",password).put("remember",remember).toString().getBytes(StandardCharsets.UTF_8);c.getOutputStream().write(data);int status=c.getResponseCode();if(status!=200)throw new Failure(status,status==429?"Too many attempts. Please wait before trying again.":"Invalid username or password.");String value="";for(var h:c.getHeaderFields().entrySet())if(h.getKey()!=null&&h.getKey().equalsIgnoreCase("Set-Cookie"))for(String item:h.getValue()){String candidate=item.split(";",2)[0];if(candidate.matches("__Host-mapping-session=[a-f0-9]{64}"))value=candidate;}if(value.isEmpty())throw new IOException("The server did not provide a Mapping session.");cookie=value;}finally{c.disconnect();}}
 void logout(){try{HttpsURLConnection c=open("/api/v1/users/logout");c.setRequestMethod("POST");c.setDoOutput(true);c.getOutputStream().write("{}".getBytes(StandardCharsets.UTF_8));c.getResponseCode();c.disconnect();}catch(Exception ignored){}cookie="";}
 String json(String path)throws Exception {String key=sha(path.getBytes(StandardCharsets.UTF_8));File file=new File(cache,key+".json"),etag=new File(cache,key+".etag");HttpsURLConnection c=open(path);try{if(file.isFile()&&etag.isFile())c.setRequestProperty("If-None-Match",readText(etag));int status=c.getResponseCode();if(status==304&&file.isFile())return readText(file);if(status!=200)throw new Failure(status,status==401?"Please sign in to Mapping again.":status==403?"Your current webapp permissions do not allow this data.":"Mapping API is unavailable ("+status+").");byte[] data=body(c,64*1024*1024);Files.write(file.toPath(),data);String e=c.getHeaderField("ETag");if(e!=null)Files.write(etag.toPath(),e.getBytes(StandardCharsets.UTF_8));else etag.delete();return new String(data,StandardCharsets.UTF_8);}finally{c.disconnect();}}
 JSONArray production(String path,String kind)throws Exception {
  String key=sha((path+"_projected_v1").getBytes(StandardCharsets.UTF_8));File file=new File(cache,key+".json"),etag=new File(cache,key+".etag");HttpsURLConnection c=open(path);
  try{if(file.isFile()&&etag.isFile())c.setRequestProperty("If-None-Match",readText(etag));int status=c.getResponseCode();if(status==304&&file.isFile())return new JSONArray(readText(file));if(status!=200)throw new Failure(status,"Production data unavailable ("+status+").");
   InputStream input=c.getInputStream();if("gzip".equalsIgnoreCase(c.getContentEncoding()))input=new GZIPInputStream(input);
   JSONArray rows=new JSONArray();try(android.util.JsonReader reader=new android.util.JsonReader(new InputStreamReader(input,StandardCharsets.UTF_8))){reader.beginObject();while(reader.hasNext()){if(!reader.nextName().equals("items")){reader.skipValue();continue;}reader.beginArray();int count=0;while(reader.hasNext()){if(++count>60000)throw new IOException("Too many mobile production records.");JSONObject out=new JSONObject().put("kind",kind);String receipt="";reader.beginObject();while(reader.hasNext()){String name=reader.nextName();String target;switch(name){case "sourceBlockCode":target="code";break;case "mapBlockCode":target="mapCode";break;case "yieldAreaHa":target="area";break;case "yieldPerHa":target="yieldApi";break;case "periodLabel":target="period";break;case "year":case "month":case "mt":case "bunches":target=name;break;case "receiptStatus":receipt=reader.nextString();continue;default:reader.skipValue();continue;}android.util.JsonToken token=reader.peek();if(token==android.util.JsonToken.NULL){reader.nextNull();out.put(target,JSONObject.NULL);}else if(token==android.util.JsonToken.NUMBER)out.put(target,reader.nextDouble());else if(token==android.util.JsonToken.STRING)out.put(target,reader.nextString());else reader.skipValue();}reader.endObject();if(receipt.equals("received")){if(!out.has("year")){String month=out.optString("month");out.put("year",month.length()>=4?Integer.parseInt(month.substring(0,4)):0);}rows.put(out);}}reader.endArray();}reader.endObject();}
   byte[] projected=rows.toString().getBytes(StandardCharsets.UTF_8);File next=new File(cache,key+".next");Files.write(next.toPath(),projected);Files.move(next.toPath(),file.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);String e=c.getHeaderField("ETag");if(e!=null)Files.write(etag.toPath(),e.getBytes(StandardCharsets.UTF_8));else etag.delete();return rows;
  }finally{c.disconnect();}
 }
 void file(JSONObject asset,File to)throws Exception {String id=asset.getString("id"),path=asset.getString("url");if(!id.matches("[A-Za-z0-9-]+")||!path.equals(API+"/assets/"+id+"/file"))throw new IOException("Unsafe map asset.");HttpsURLConnection c=open(path);try{int status=c.getResponseCode();if(status!=200)throw new Failure(status,"Map file download was refused ("+status+").");byte[] bytes=body(c,32*1024*1024);if(!sha(bytes).equals(asset.getString("sha256")))throw new IOException("Map checksum did not match. Saved map kept unchanged.");Files.write(to.toPath(),bytes);}finally{c.disconnect();}}
}
